select concat_ws(' - ', Min(`card_number`), MAX(`card_number`)) as `numberSegment`, `org_id` as `allocateOrgId` from `card` where `coupon_id` = #{couponId} and `coupon_allocate_id` in
#{item}
group by `coupon_allocate_id`,`org_id`

select
    `card_number`,
    `card_password`,
    `org_id`
from `card`
where `coupon_id` = #{couponId}
and `coupon_allocate_id` in

    #{item}

order by `card_number` asc;

select `id`, `card_number`, `card_password`, `sold_target`, `sold_phone_number`, `sold_type`, `status`, `is_pay`, `sold_way`, `pay_id`, `remark` from `card` where `coupon_id` = #{couponId} and `org_id` = #{orgId}
and `card_number` like concat('%', #{cardNumber}, '%')
and `sold_phone_number` like concat('%', #{phoneNumber}, '%')
and `sold_type` in
#{item}
and `status` in
#{item}
order by `status` asc, `id` asc

select
    count(`id`) - ifnull(sum(`status` in (1, 2, 3 , 4)),0)
from `card`
where `coupon_id` = #{couponId}
  and `org_id` = #{orgId}
group by `coupon_id`, `org_id`;

select `c`.remark, `c`.`id` as `cardId`, `cci`.`id` as `couponId`, `cci`.`name` as `couponName`, case when `c`.`org_id` = 0 then `c`.`third_card_number` else `c`.`card_number` end as `cardNumber`, `cci`.`type` as `couponType`, `cci`.`product_type_id`, `cci`.`is_inservice` as `couponEnable`, `c`.`sale_channel_id`, case when `cci`.`type` = 2 then (select `use_way` from `package_coupon` where `coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 3 then (select `use_way` from `special_package_coupon` where `coupon_id` = `c`.`coupon_id`) else null end as `useWay`, case when `cci`.`type` = 0 then (select if(isnull(`c`.`active_date`), null, if(isnull(`vc`.`activation_deadline`), if(`vc`.`effective_days` = 0, null, date_format(date_add(`c`.`active_date`, interval `vc`.`effective_days` day), '%Y-%m-%d')), if(date_format(`vc`.`activation_deadline`, '%Y-%m-%d') > date_format(date_add(`c`.`active_date`, interval ifnull(`vc`.`effective_days`, 0) day), '%Y-%m-%d'), date_format(date_add(`c`.`active_date`, interval ifnull(`vc`.`effective_days`, 0) day), '%Y-%m-%d'), date_format(`vc`.`activation_deadline`, '%Y-%m-%d')))) from `vouche_coupon` `vc` where `vc`.`coupon_id` = `c`.coupon_id) when `cci`.`type` = 1 then (select if(isnull(`c`.`active_date`), null, if(isnull(`dc`.`activation_deadline`), if(`dc`.`effective_days` = 0, null, date_format(date_add(`c`.`active_date`, interval `dc`.`effective_days` day), '%Y-%m-%d')), if(date_format(`dc`.`activation_deadline`, '%Y-%m-%d') > date_format(date_add(`c`.`active_date`, interval ifnull(`dc`.`effective_days`, 0) day), '%Y-%m-%d'), date_format(date_add(`c`.`active_date`, interval ifnull(`dc`.`effective_days`, 0) day), '%Y-%m-%d'), date_format(`dc`.`activation_deadline`, '%Y-%m-%d')))) from `discount_coupon` `dc` where `dc`.`coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 2 then (select if(isnull(`c`.`active_date`), null, if(isnull(`pc`.`activation_deadline`), if(`pc`.`effective_days` = 0, null, date_format(date_add(`c`.`active_date`, interval `pc`.`effective_days` day), '%Y-%m-%d')), if(date_format(`pc`.`activation_deadline`, '%Y-%m-%d') > date_format(date_add(`c`.`active_date`, interval ifnull(`pc`.`effective_days`, 0) day), '%Y-%m-%d'), date_format(date_add(`c`.`active_date`, interval ifnull(`pc`.`effective_days`, 0) day), '%Y-%m-%d'), date_format(`pc`.`activation_deadline`, '%Y-%m-%d')))) from `package_coupon` `pc` where `pc`.`coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 3 then (select if(isnull(`c`.`active_date`), null, if(isnull(`spc`.`activation_deadline`), if(`spc`.`effective_days` = 0, null, date_format(date_add(`c`.`active_date`, interval `spc`.`effective_days` day), '%Y-%m-%d')), if(date_format(`spc`.`activation_deadline`, '%Y-%m-%d') > date_format(date_add(`c`.`active_date`, interval ifnull(`spc`.`effective_days`, 0) day), '%Y-%m-%d'), date_format(date_add(`c`.`active_date`, interval ifnull(`spc`.`effective_days`, 0) day), '%Y-%m-%d'), date_format(`spc`.`activation_deadline`, '%Y-%m-%d')))) from `special_package_coupon` `spc` where `spc`.`coupon_id` = `c`.`coupon_id`) else null end as `useDeadline`, date_format(`c`.`active_date`, '%Y-%m-%d') as `activeDate`, case when `cci`.`type` = 0 then (select `is_share` from `vouche_coupon` where `coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 1 then (select `is_share` from `discount_coupon` where `coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 2 then (select `is_share` from `package_coupon` where `coupon_id` = `c`.`coupon_id`) when `cci`.`type` = 3 then (select `is_share` from `special_package_coupon` where `coupon_id` = `c`.`coupon_id`) else null end as `share`
, `c`.`patient_id` as `cardOwner`
from `card` `c` inner join `coupon_common_info` `cci` on `c`.`coupon_id` = `cci`.`id` where `c`.`status` in (2,3,4) and `cci`.type != 5
and `c`.`patient_id` = #{patientId}
and find_in_set(#{patientId}, `c`.`sharer`) and `c`.`patient_id` != #{patientId}
and `cci`.`name` like concat('%', #{couponName}, '%')
and `cci`.`type` in
#{item}
order by `activeDate` desc

select case when cci.type = 0 then ( select vc.useable_clinci from vouche_coupon vc where vc.coupon_id = cci.id ) when cci.type = 1 then ( select dc.useable_clinic from discount_coupon dc where dc.coupon_id = cci.id ) when cci.type = 2 then ( select pc.useable_clinic from package_coupon pc where pc.coupon_id = cci.id ) when cci.type = 3 then ( select spc.useable_clinic from special_package_coupon spc where spc.coupon_id = cci.id ) when cci.type = 5 then ( select dc.useable_clinic from deduction_coupon dc where dc.coupon_id = cci.id ) else null end as useClinicIdStr, cci.id as couponId from coupon_common_info cci where cci.id in
#{item}
and cci.is_inservice = 1;

select
pci.coupon_id as couponId, pci.item_id as itemId, pci.type, pci.count as originCount, if(temp.useCount >= pci.count, 0, 1) as usable,
spci.coupon_id as couponId, spci.item_id as itemId, spci.type, spci.count as originCount, if(temp.useCount >= spci.count, 0, 1) as usable, spci.package_unit_price as packageUnitPrice,
dip.coupon_id as couponId, dip.item_id as itemId, dip.type, dip.count as originCount, if(temp.useCount >= dip.count, 0, 1) as usable, dip.package_unit_price as packageUnitPrice,
if(isnull(temp.card_id) = 1, #{cardId}, temp.card_id) as cardId, if(isnull(temp.useCount) = 1, 0, temp.useCount) as useCount from (select cb.coupon_id, cb.card_id, cb.item_id, count(*) as useCount from card_benefit cb where cb.card_id = #{cardId} and cb.is_deleted = 0 group by cb.coupon_id, cb.card_id, cb.item_id) temp left join `card` `c` on `c`.`id` = `temp`.`card_id` right join
package_coupon_item pci on temp.coupon_id = pci.coupon_id and temp.item_id = pci.item_id
special_package_coupon_item spci on temp.coupon_id = spci.coupon_id and temp.item_id = spci.item_id
deduction_item_period dip on temp.coupon_id = dip.coupon_id and temp.item_id = dip.item_id and dip.type = #{couponType}
where
pci.coupon_id = #{couponId}
and pci.type = #{type}
spci.coupon_id = #{couponId}
and spci.type = #{type}
dip.coupon_id = #{couponId} and dip.crt_time = (select max(crt_time) from deduction_item_period where coupon_id = #{couponId} and crt_time <= ifnull(c.sold_date, c.active_date))

select sum(t2.sold_amount) from card t1 LEFT JOIN coupon_common_info t2 on t1.coupon_id=t2.id
t1.sold_type=0
and DATE_FORMAT(t1.sold_date,'%Y-%m-%d') >= DATE_FORMAT(#{query.startDate},'%Y-%m-%d')
and DATE_FORMAT(t1.sold_date,'%Y-%m-%d') <= DATE_FORMAT(#{query.endDate},'%Y-%m-%d')
and t1.org_id = #{query.orgId}
and t1.pay_id = #{query.payId}

select `sharer` from `card` where `patient_id` = #{patientId}
and `coupon_id` = #{couponId}
and isnull(`active_date`) = 0 order by `active_date` desc limit 1

select
    count(*)
from `card`
where `patient_id` = #{patientId}

        and `coupon_id` = #{couponId}

    and isnull(`active_date`) = 0

